import React, { useEffect, useState, useRef, useCallback } from 'react'
import axios from 'axios'
import { useTheme } from '../component/ThemeContext'

export default function LocalAi() {
  const { theme } = useTheme()
  const isDark = theme === 'dark'
  const containerRef = useRef(null)
  const messagesEndRef = useRef(null)
  const [models, setModels] = useState([])
  const [selectedModel, setSelectedModel] = useState('')
  const [input, setInput] = useState('')
  const [history, setHistory] = useState([]) // {role: 'user'|'assistant', content}
  const [loading, setLoading] = useState(false)
  const [fetchingModels, setFetchingModels] = useState(true)
  const [error, setError] = useState('')
  const [modelsLastUpdated, setModelsLastUpdated] = useState(null)
  const [autoRefreshEnabled, setAutoRefreshEnabled] = useState(true)
  const [modelsChangedNotification, setModelsChangedNotification] = useState('')
  const mountedRef = useRef(true)
  const pollIntervalRef = useRef(null)
  const previousModelsRef = useRef([])

// Helper functions for parsing and rendering content
function splitIntoSegments(raw) {
  const segments = [];
  let cursor = 0;
  const src = raw || "";
  while (cursor < src.length) {
    const open = src.indexOf("```", cursor);
    if (open === -1) {
      if (cursor < src.length) segments.push({ type: "text", content: src.slice(cursor) });
      break;
    }
    if (open > cursor) segments.push({ type: "text", content: src.slice(cursor, open) });
    const afterTicks = open + 3;
    const lineEnd = src.indexOf("\n", afterTicks);
    let codeStart;
    let lang = "";
    if (lineEnd === -1) {
      codeStart = afterTicks;
    } else {
      const maybeLang = src.slice(afterTicks, lineEnd).trim();
      if (maybeLang && /^[\w#+.:-]+$/.test(maybeLang)) {
        lang = maybeLang;
        codeStart = lineEnd + 1;
      } else {
        codeStart = afterTicks;
      }
    }
    const close = src.indexOf("```", codeStart);
    if (close === -1) {
      segments.push({ type: "text", content: src.slice(open) });
      break;
    }
    const code = src.slice(codeStart, close).replace(/\n$/, "");
    segments.push({ type: "code", lang, code });
    cursor = close + 3;
  }
  return segments;
}

function renderInline(text, isDark) {
  const parts = String(text).split(/(\*\*[^*]+\*\*)/g);
  return parts.map((part, idx) => {
    if (part.startsWith("**") && part.endsWith("**") && part.length > 4) {
      const inner = part.slice(2, -2);
      return (
        <strong key={idx} style={{ fontWeight: 700, color: isDark ? "#f1f5f9" : "#312e81" }}>
          {inner}
        </strong>
      );
    }
    return <span key={idx}>{part}</span>;
  });
}

function renderTextBlock(content, baseKey, isDark) {
  const lines = content.replace(/\r\n/g, "\n").split("\n");
  const elements = [];
  let paraBuf = [];
  let key = 0;

  const flushPara = () => {
    if (paraBuf.length === 0) return;
    const paraText = paraBuf.join("\n").trim();
    paraBuf = [];
    if (!paraText) return;
    elements.push(
      <p key={`${baseKey}-p-${key++}`} style={{ margin: "0 0 10px", lineHeight: 1.55, color: isDark ? "#e2e8f0" : "#334155" }}>
        {renderInline(paraText, isDark)}
      </p>
    );
  };

  let i = 0;
  while (i < lines.length) {
    const line = lines[i];
    const trimmed = line.trim();
    if (!trimmed) {
      flushPara();
      i += 1;
      continue;
    }

    if (/^#{1,3}\s+/.test(trimmed)) {
      flushPara();
      const level = trimmed.match(/^#+/)[0].length;
      const text = trimmed.replace(/^#+\s+/, "");
      const HeadingTag = level === 1 ? "h3" : level === 2 ? "h4" : "h5";
      const size = level === 1 ? "1.15rem" : level === 2 ? "1.05rem" : "1rem";
      elements.push(
        <HeadingTag
          key={`${baseKey}-h-${key++}`}
          style={{
            margin: "14px 0 8px",
            fontWeight: 700,
            color: isDark ? "#f1f5f9" : "#1e293b",
            fontSize: size,
            lineHeight: 1.35,
          }}
        >
          {renderInline(text, isDark)}
        </HeadingTag>
      );
      i += 1;
      continue;
    }

    if (/^\*\*(.+)\*\*$/.test(trimmed)) {
      flushPara();
      const inner = trimmed.slice(2, -2);
      elements.push(
        <h4
          key={`${baseKey}-boldline-${key++}`}
          style={{
            margin: "12px 0 6px",
            fontWeight: 700,
            fontSize: "1.02rem",
            color: isDark ? "#f1f5f9" : "#1e293b",
            lineHeight: 1.35,
          }}
        >
          {inner}
        </h4>
      );
      i += 1;
      continue;
    }

    if (/^[-*•]\s+/.test(trimmed)) {
      flushPara();
      const items = [];
      while (i < lines.length && /^[-*•]\s+/.test(lines[i].trim())) {
        items.push(lines[i].trim().replace(/^[-*•]\s+/, ""));
        i += 1;
      }
      elements.push(
        <ul
          key={`${baseKey}-ul-${key++}`}
          style={{
            margin: "6px 0 12px",
            paddingLeft: 22,
            color: isDark ? "#cbd5e1" : "#334155",
            lineHeight: 1.55,
          }}
        >
          {items.map((it, j) => (
            <li key={j} style={{ marginBottom: 6 }}>
              {renderInline(it, isDark)}
            </li>
          ))}
        </ul>
      );
      continue;
    }

    if (/^\d+\.\s+/.test(trimmed)) {
      flushPara();
      const items = [];
      while (i < lines.length && /^\d+\.\s+/.test(lines[i].trim())) {
        items.push(lines[i].trim().replace(/^\d+\.\s+/, ""));
        i += 1;
      }
      elements.push(
        <ol
          key={`${baseKey}-ol-${key++}`}
          style={{
            margin: "6px 0 12px",
            paddingLeft: 22,
            color: isDark ? "#cbd5e1" : "#334155",
            lineHeight: 1.55,
          }}
        >
          {items.map((it, j) => (
            <li key={j} style={{ marginBottom: 6 }}>
              {renderInline(it, isDark)}
            </li>
          ))}
        </ol>
      );
      continue;
    }

    paraBuf.push(line);
    i += 1;
  }
  flushPara();
  return elements;
}

function CodeBlock({ lang, code, isDark }) {
  const [copied, setCopied] = useState(false);

  const copy = useCallback(() => {
    navigator.clipboard.writeText(code).then(() => {
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    });
  }, [code]);

  const codeShell = {
    position: "relative",
    margin: "12px 0",
    borderRadius: 8,
    border: `1px solid ${isDark ? '#334155' : '#d1d5db'}`,
    background: isDark ? '#0f172a' : '#f8fafc',
    overflow: "hidden",
  };

  const codePre = {
    margin: 0,
    padding: "12px 14px 14px",
    overflowX: "auto",
    fontSize: 13,
    lineHeight: 1.5,
    fontFamily: "ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace",
    color: isDark ? '#e2e8f0' : '#1f2937',
  };

  return (
    <div style={codeShell}>
      <div
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
          gap: 8,
          padding: "6px 10px",
          background: isDark ? '#1e293b' : '#e5e7eb',
          borderBottom: `1px solid ${isDark ? '#334155' : '#d1d5db'}`,
        }}
      >
        <span style={{ fontSize: 11, color: isDark ? '#94a3b8' : '#6b7280', textTransform: "uppercase", letterSpacing: "0.04em" }}>
          {lang || "code"}
        </span>
        <button
          type="button"
          onClick={copy}
          style={{
            cursor: "pointer",
            fontSize: 12,
            padding: "4px 10px",
            borderRadius: 6,
            border: `1px solid ${isDark ? '#475569' : '#9ca3af'}`,
            background: copied ? (isDark ? '#22c55e' : '#16a34a') : (isDark ? '#334155' : '#d1d5db'),
            color: copied ? '#ffffff' : (isDark ? '#f8fafc' : '#374151'),
            transition: 'all 0.2s'
          }}
        >
          {copied ? "Copied!" : "Copy"}
        </button>
      </div>
      <pre style={codePre}>
        <code>{code}</code>
      </pre>
    </div>
  );
}

function AssistantOutput({ text, isDark }) {
  const segments = splitIntoSegments(text);
  const assistantShell = {
    marginTop: 8,
    padding: "14px 16px",
    borderRadius: 10,
    border: `1px solid ${isDark ? '#334155' : '#e2e8f0'}`,
    background: isDark ? "linear-gradient(180deg, #1e293b 0%, #0f172a 100%)" : "linear-gradient(180deg, #f8fafc 0%, #f1f5f9 100%)",
    borderLeft: `4px solid ${isDark ? '#6366f1' : '#6366f1'}`,
  };

  return (
    <div style={assistantShell} aria-label="AI reply">
      {segments.map((seg, idx) => {
        if (seg.type === "code") {
          return <CodeBlock key={`c-${idx}`} lang={seg.lang} code={seg.code} isDark={isDark} />;
        }
        return <div key={`t-${idx}`}>{renderTextBlock(seg.content, `seg-${idx}`, isDark)}</div>;
      })}
    </div>
  );
}

// Fetch models function - defined with useCallback to avoid recreation
  const fetchModels = useCallback(async (isPolling = false) => {
    try {
      if (!isPolling) setFetchingModels(true)
      setError('')
      const res = await axios.get('http://localhost:11434/api/tags', { timeout: 5000 })
      if (!mountedRef.current) return

      // Ollama returns { models: [{ name, size, ...}] }
      if (res.data && res.data.models && Array.isArray(res.data.models)) {
        const modelNames = res.data.models.map(m => m.name).sort()
        const previousModels = previousModelsRef.current

        // Check if models changed
        const modelsChanged = JSON.stringify(previousModels.sort()) !== JSON.stringify(modelNames)

        setModels(modelNames)
        previousModelsRef.current = modelNames
        setModelsLastUpdated(new Date())

        // Show notification if models changed during polling
        if (isPolling && modelsChanged && previousModels.length > 0) {
          const added = modelNames.filter(m => !previousModels.includes(m))
          const removed = previousModels.filter(m => !modelNames.includes(m))

          let notification = 'Models updated: '
          if (added.length > 0) notification += `+${added.join(', ')} `
          if (removed.length > 0) notification += `-${removed.join(', ')}`

          setModelsChangedNotification(notification)
          // Auto-hide notification after 5 seconds
          setTimeout(() => setModelsChangedNotification(''), 5000)
        }

        // Handle model selection changes
        if (selectedModel && !modelNames.includes(selectedModel)) {
          setSelectedModel(modelNames.length > 0 ? modelNames[0] : '')
          if (modelNames.length === 0) {
            setError('No models available. Please install a model with: ollama pull <model-name>')
          } else {
            setError(`Selected model "${selectedModel}" is no longer available. Switched to "${modelNames[0]}".`)
          }
        } else if (modelNames.length > 0 && !selectedModel) {
          setSelectedModel(modelNames[0])
        }

        // Clear error if we successfully fetched models
        if (modelNames.length > 0) {
          setError('')
        }
      } else {
        throw new Error('Invalid response format')
      }
    } catch (err) {
      if (!mountedRef.current) return
      console.warn('Failed to fetch models from Ollama:', err.message)
      setError('Could not connect to Ollama. Make sure Ollama is running on localhost:11434')
      // Fallback models
      const fallbackModels = ['qwen2.5-coder:3b', 'llama3.2:3b', 'qwen3:4b']
      setModels(fallbackModels)
      previousModelsRef.current = fallbackModels
      if (!selectedModel) {
        setSelectedModel(fallbackModels[0])
      }
    } finally {
      if (mountedRef.current && !isPolling) setFetchingModels(false)
    }
  }, [selectedModel]);
  useEffect(() => {
  let isMounted = true;

  // Initial fetch
  const initialFetch = async () => {
    if (isMounted) {
      await fetchModels();
    }
  };
  initialFetch();

  // Set up polling if enabled
  let intervalId = null;
  if (autoRefreshEnabled) {
    intervalId = setInterval(() => {
      if (isMounted) {
        fetchModels(true);
      }
    }, 10000); // Check every 10 seconds
  }

  return () => {
    isMounted = false;
    if (intervalId) {
      clearInterval(intervalId);
    }
  };
}, [autoRefreshEnabled]); 
// Only depend on autoRefreshEnabled
  const refreshModels = () => {
    setFetchingModels(true)
    setError('')
    setModelsChangedNotification('')
    fetchModels(false)
  }

  const composePrompt = (messages) => {
    // simple conversation formatting for models that accept plain prompts
    return messages.map(m => (m.role === 'user' ? `User: ${m.content}` : `Assistant: ${m.content}`)).join('\n') + '\nAssistant:'
  }

 const parseResponseText = (data) => {
  if (!data) return ''
  if (typeof data === 'string') return data
  // ✅ Ollama /api/generate returns { response: "..." }
  if (data.response) return data.response
  if (data.text) return data.text
  if (data.message && data.message.content) return data.message.content
  if (data.choices && Array.isArray(data.choices) && data.choices[0]) {
    const ch = data.choices[0]
    if (ch.text) return ch.text
    if (ch.message && ch.message.content) return ch.message.content
  }
  try { return JSON.stringify(data) } catch (e) { return String(data) }
}

  const sendMessage = async () => {
    if (!input.trim() || !selectedModel || !models.includes(selectedModel)) return
    
    // Check if model is still available
    if (!models.includes(selectedModel)) {
      setError(`Model "${selectedModel}" is no longer available. Please select a different model.`)
      return
    }
    const userMsg = { role: 'user', content: input.trim() }
    const newHistory = [...history, userMsg]
    setHistory(newHistory)
    setInput('')
    setLoading(true)
    setError('')

    try {
      const prompt = composePrompt(newHistory)

      // POST to Ollama local API with correct parameters
      const res = await axios.post('http://localhost:11434/api/generate', {
        model: selectedModel,
        prompt,
        stream: false, // Get complete response at once
        options: {
          num_predict: 512, // max tokens
          temperature: 0.2,
        }
      }, {
        headers: { 'Content-Type': 'application/json' },
        timeout: 120000,
      })

      const assistantText = parseResponseText(res.data)
      const assistantMsg = { role: 'assistant', content: assistantText }
      setHistory(prev => [...prev, assistantMsg])
    } catch (err) {
      console.error('AI request failed:', err)
      let errorMessage = 'Failed to get response from AI'
      
      if (err.code === 'ECONNREFUSED') {
        errorMessage = 'Cannot connect to Ollama. Make sure Ollama is running on localhost:11434'
      } else if (err.response) {
        errorMessage = `API Error: ${err.response.status} - ${err.response.statusText}`
      } else if (err.message) {
        errorMessage = `Error: ${err.message}`
      }
      
      setHistory(prev => [...prev, { role: 'assistant', content: errorMessage }])
      setError(errorMessage)
    } finally {
      if (mountedRef.current) setLoading(false)
    }
  }

  const handleKeyDown = (e) => {
    if (e.key === 'Enter' && (e.ctrlKey || e.metaKey)) sendMessage()
  }

  useEffect(() => {
    // scroll to bottom when history updates
    if (messagesEndRef.current) messagesEndRef.current.scrollIntoView({ behavior: 'smooth' })
  }, [history])

  const toggleFullScreen = () => {
    const el = containerRef.current
    if (!el) return
    if (!document.fullscreenElement) {
      if (el.requestFullscreen) el.requestFullscreen()
    } else {
      if (document.exitFullscreen) document.exitFullscreen()
    }
  }

  const summarizeChat = async () => {
    if (history.length === 0 || !selectedModel) return
    const chatText = history.map(m => `${m.role === 'user' ? 'User' : 'Assistant'}: ${m.content}`).join('\n')
    const prompt = `Please provide a concise summary of the following conversation:\n\n${chatText}`
    setInput('')
    setLoading(true)
    setError('')

    try {
      const res = await axios.post('http://localhost:11434/api/generate', {
        model: selectedModel,
        prompt,
        stream: false,
        options: {
          num_predict: 256,
          temperature: 0.1,
        }
      }, {
        headers: { 'Content-Type': 'application/json' },
        timeout: 60000,
      })

      const summaryText = parseResponseText(res.data)
      const summaryMsg = { role: 'assistant', content: `**Chat Summary:**\n\n${summaryText}` }
      setHistory(prev => [...prev, summaryMsg])
    } catch (err) {
      setError('Failed to generate summary')
    } finally {
      setLoading(false)
    }
  }

  const bg = isDark ? '#0b1220' : '#f7fafc'
  const cardBg = isDark ? '#0f1724' : '#ffffff'
  const textColor = isDark ? '#e6eef8' : '#0f1724'
  const borderColor = isDark ? 'rgba(255,255,255,0.1)' : 'rgba(0,0,0,0.08)'
  const accentColor = '#3b82f6'

  return (
    <div ref={containerRef} style={{ 
      maxWidth: 1200, 
      margin: '0 auto', 
      padding: 20, 
      background: bg, 
      color: textColor, 
      borderRadius: 12,
      minHeight: '100vh'
    }}>
      {/* Header */}
      <div style={{ 
        display: 'flex', 
        justifyContent: 'space-between', 
        alignItems: 'center', 
        marginBottom: 20,
        padding: '16px 20px',
        background: cardBg,
        borderRadius: 12,
        boxShadow: isDark ? '0 4px 20px rgba(0,0,0,0.3)' : '0 2px 10px rgba(0,0,0,0.05)',
        border: `1px solid ${borderColor}`
      }}>
        <div>
          <h2 style={{ margin: 0, fontSize: '1.5rem', fontWeight: 600 }}>🤖 Local AI Chat</h2>
          <p style={{ margin: '4px 0 0 0', fontSize: '0.875rem', color: isDark ? '#94a3b8' : '#6b7280' }}>
            {models.length} models available
            {modelsLastUpdated && (
              <span style={{ marginLeft: 8, fontSize: '0.75rem' }}>
                • Updated {modelsLastUpdated.toLocaleTimeString()}
              </span>
            )}
            {autoRefreshEnabled && (
              <span style={{ marginLeft: 8, fontSize: '0.75rem', color: accentColor }}>
                • Auto-refresh active
              </span>
            )}
          </p>
        </div>
        
        <div style={{ display: 'flex', gap: 16, alignItems: 'center' }}>
          {/* Model Selector */}
          <div style={{ display: 'flex', flexDirection: 'column', gap: 4 }}>
            <label style={{ fontSize: '0.75rem', fontWeight: 500, color: isDark ? '#cbd5e1' : '#374151' }}>
              AI Model ({models.length})
            </label>
            <div style={{ display: 'flex', gap: 8, alignItems: 'center' }}>
              <select 
                value={selectedModel} 
                onChange={e => setSelectedModel(e.target.value)} 
                disabled={fetchingModels || models.length === 0}
                style={{ 
                  padding: '8px 12px', 
                  borderRadius: 8, 
                  border: `1px solid ${borderColor}`,
                  background: isDark ? '#1e293b' : '#ffffff',
                  color: textColor,
                  fontSize: '0.875rem',
                  minWidth: 200,
                  flex: 1
                }}
              >
                {fetchingModels ? (
                  <option>Loading models...</option>
                ) : models.length === 0 ? (
                  <option>No models available</option>
                ) : (
                  models.map(m => <option key={m} value={m}>{m}</option>)
                )}
              </select>
              <button 
                onClick={refreshModels}
                disabled={fetchingModels}
                title="Refresh models list"
                style={{ 
                  padding: '8px 12px',
                  borderRadius: 8,
                  border: `1px solid ${borderColor}`,
                  background: 'transparent',
                  color: textColor,
                  cursor: fetchingModels ? 'not-allowed' : 'pointer',
                  opacity: fetchingModels ? 0.5 : 1,
                  display: 'flex',
                  alignItems: 'center',
                  gap: 4
                }}
              >
                {fetchingModels ? (
                  <div className="spinner-border spinner-border-sm" role="status"></div>
                ) : (
                  <>
                    <i className="bi bi-arrow-clockwise"></i>
                    <span style={{ fontSize: '0.75rem' }}>Refresh</span>
                  </>
                )}
              </button>
            </div>
          </div>

          {/* Auto-refresh Toggle */}
          <div style={{ display: 'flex', flexDirection: 'column', gap: 4 }}>
            <label style={{ fontSize: '0.75rem', fontWeight: 500, color: isDark ? '#cbd5e1' : '#374151' }}>
              Auto-refresh
            </label>
            <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
              <label className="switch" style={{ position: 'relative', display: 'inline-block', width: 44, height: 24 }}>
                <input 
                  type="checkbox" 
                  checked={autoRefreshEnabled}
                  onChange={e => setAutoRefreshEnabled(e.target.checked)}
                  style={{ opacity: 0, width: 0, height: 0 }}
                />
                <span style={{
                  position: 'absolute',
                  cursor: 'pointer',
                  top: 0,
                  left: 0,
                  right: 0,
                  bottom: 0,
                  backgroundColor: autoRefreshEnabled ? accentColor : (isDark ? '#475569' : '#d1d5db'),
                  transition: '.2s',
                  borderRadius: 24,
                  border: `1px solid ${borderColor}`
                }}>
                  <span style={{
                    position: 'absolute',
                    content: '""',
                    height: 16,
                    width: 16,
                    left: autoRefreshEnabled ? 20 : 4,
                    bottom: 4,
                    backgroundColor: 'white',
                    transition: '.2s',
                    borderRadius: '50%'
                  }}></span>
                </span>
              </label>
              <span style={{ fontSize: '0.75rem', color: isDark ? '#cbd5e1' : '#6b7280' }}>
                {autoRefreshEnabled ? 'On (10s)' : 'Off'}
              </span>
            </div>
          </div>

          {/* Action Buttons */}
          <div style={{ display: 'flex', gap: 8 }}>
            <button 
              onClick={toggleFullScreen} 
              title="Toggle fullscreen"
              style={{ 
                padding: '8px 12px',
                borderRadius: 8,
                border: `1px solid ${borderColor}`,
                background: 'transparent',
                color: textColor,
                cursor: 'pointer',
                fontSize: '0.875rem'
              }}
            >
              <i className="bi bi-fullscreen"></i>
            </button>
            <button 
              onClick={summarizeChat}
              disabled={history.length === 0 || loading || !selectedModel}
              title="Summarize chat"
              style={{ 
                padding: '8px 12px',
                borderRadius: 8,
                border: `1px solid ${borderColor}`,
                background: 'transparent',
                color: textColor,
                cursor: (history.length > 0 && !loading && selectedModel) ? 'pointer' : 'not-allowed',
                opacity: (history.length > 0 && !loading && selectedModel) ? 1 : 0.5,
                fontSize: '0.875rem'
              }}
            >
              <i className="bi bi-file-earmark-text"></i>
            </button>
            <button 
              onClick={() => { setHistory([]); setInput(''); setError('') }} 
              title="Clear chat"
              style={{ 
                padding: '8px 12px',
                borderRadius: 8,
                border: `1px solid ${borderColor}`,
                background: 'transparent',
                color: textColor,
                cursor: 'pointer',
                fontSize: '0.875rem'
              }}
            >
              <i className="bi bi-trash3"></i>
            </button>
          </div>
        </div>
      </div>

      {/* Error Banner */}
      {error && (
        <div style={{
          padding: '12px 16px',
          marginBottom: 16,
          borderRadius: 8,
          background: isDark ? '#dc26261a' : '#fef2f2',
          border: `1px solid ${isDark ? '#dc26263d' : '#fecaca'}`,
          color: isDark ? '#fca5a5' : '#dc2626'
        }}>
          <i className="bi bi-exclamation-triangle me-2"></i>
          {error}
        </div>
      )}

      {/* Models Changed Notification */}
      {modelsChangedNotification && (
        <div style={{
          padding: '12px 16px',
          marginBottom: 16,
          borderRadius: 8,
          background: isDark ? '#10b9811a' : '#f0fdf4',
          border: `1px solid ${isDark ? '#10b9813d' : '#bbf7d0'}`,
          color: isDark ? '#6ee7b7' : '#166534',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between'
        }}>
          <div>
            <i className="bi bi-check-circle me-2"></i>
            {modelsChangedNotification}
          </div>
          <button 
            onClick={() => setModelsChangedNotification('')}
            style={{
              background: 'transparent',
              border: 'none',
              color: 'inherit',
              cursor: 'pointer',
              fontSize: '1.2em',
              padding: 0,
              marginLeft: 8
            }}
          >
            ×
          </button>
        </div>
      )}

      {/* Chat Container */}
      <div style={{ 
        borderRadius: 12, 
        background: cardBg, 
        padding: 20, 
        minHeight: 400, 
        maxHeight: 600, 
        overflowY: 'auto', 
        boxShadow: isDark ? '0 8px 32px rgba(0,0,0,0.4)' : '0 4px 16px rgba(0,0,0,0.06)',
        border: `1px solid ${borderColor}`,
        display: 'flex',
        flexDirection: 'column'
      }}>
        {history.length === 0 ? (
          <div style={{ 
            display: 'flex', 
            flexDirection: 'column', 
            alignItems: 'center', 
            justifyContent: 'center', 
            flex: 1,
            color: isDark ? '#64748b' : '#9ca3af',
            textAlign: 'center'
          }}>
            <i className="bi bi-chat-dots" style={{ fontSize: '3rem', marginBottom: 16, opacity: 0.5 }}></i>
            <h4 style={{ margin: 0, fontWeight: 500 }}>Start a conversation</h4>
            <p style={{ margin: '8px 0 0 0', fontSize: '0.875rem' }}>
              Type your message below and press Send or Ctrl+Enter
            </p>
          </div>
        ) : (
          <>
            {history.map((m, i) => (
              <div key={i} style={{ 
                display: 'flex', 
                marginBottom: 16, 
                justifyContent: m.role === 'user' ? 'flex-end' : 'flex-start' 
              }}>
                <div style={{ 
                  maxWidth: '80%', 
                  padding: m.role === 'assistant' ? '0' : '12px 16px', 
                  borderRadius: 16, 
                  background: m.role === 'user' 
                    ? (isDark ? accentColor : '#3b82f6') 
                    : 'transparent', 
                  color: m.role === 'user' ? '#ffffff' : textColor, 
                  whiteSpace: m.role === 'user' ? 'pre-wrap' : 'normal',
                  border: m.role === 'assistant' ? 'none' : 'none',
                  boxShadow: m.role === 'user' ? '0 2px 8px rgba(59, 130, 246, 0.3)' : 'none'
                }}>
                  <div style={{ 
                    fontSize: '0.75rem', 
                    opacity: 0.8, 
                    marginBottom: 8,
                    fontWeight: 500
                  }}>
                    {m.role === 'user' ? 'You' : 'AI Assistant'}
                  </div>
                  {m.role === 'user' ? (
                    <div style={{ lineHeight: 1.5, whiteSpace: 'pre-wrap' }}>{m.content}</div>
                  ) : (
                    <AssistantOutput text={m.content} isDark={isDark} />
                  )}
                </div>
              </div>
            ))}
            {loading && (
              <div style={{ display: 'flex', justifyContent: 'flex-start', marginBottom: 16 }}>
                <div style={{ 
                  padding: '12px 16px', 
                  borderRadius: 16, 
                  background: isDark ? '#1e293b' : '#f8fafc',
                  border: `1px solid ${borderColor}`,
                  display: 'flex',
                  alignItems: 'center',
                  gap: 8
                }}>
                  <div className="spinner-border spinner-border-sm" role="status"></div>
                  <span style={{ fontSize: '0.875rem', color: isDark ? '#cbd5e1' : '#6b7280' }}>
                    AI is thinking...
                  </span>
                </div>
              </div>
            )}
          </>
        )}
        <div ref={messagesEndRef} />
      </div>

      {/* Input Area */}
      <div style={{ 
        marginTop: 16, 
        display: 'flex', 
        gap: 12, 
        alignItems: 'flex-end',
        background: cardBg,
        padding: 16,
        borderRadius: 12,
        border: `1px solid ${borderColor}`,
        boxShadow: isDark ? '0 4px 20px rgba(0,0,0,0.3)' : '0 2px 10px rgba(0,0,0,0.05)'
      }}>
        <div style={{ flex: 1 }}>
          <textarea
            value={input}
            onChange={e => setInput(e.target.value)}
            onKeyDown={handleKeyDown}
            placeholder="Type your message here... (Ctrl+Enter to send)"
            rows={3}
            disabled={loading || !selectedModel}
            style={{ 
              width: '100%', 
              padding: 12, 
              borderRadius: 8, 
              border: `1px solid ${borderColor}`,
              background: isDark ? '#1e293b' : '#ffffff',
              color: textColor,
              fontSize: '0.875rem',
              resize: 'vertical',
              outline: 'none'
            }}
          />
          <div style={{ 
            fontSize: '0.75rem', 
            color: isDark ? '#64748b' : '#9ca3af', 
            marginTop: 4 
          }}>
            Press Ctrl+Enter to send • {input.length} characters
          </div>
        </div>
        <button 
          onClick={sendMessage} 
          disabled={loading || !input.trim() || !selectedModel}
          style={{ 
            padding: '12px 20px',
            borderRadius: 8,
            border: 'none',
            background: (!loading && input.trim() && selectedModel) ? accentColor : (isDark ? '#475569' : '#d1d5db'),
            color: '#ffffff',
            cursor: (!loading && input.trim() && selectedModel) ? 'pointer' : 'not-allowed',
            fontSize: '0.875rem',
            fontWeight: 500,
            display: 'flex',
            alignItems: 'center',
            gap: 8,
            transition: 'all 0.2s'
          }}
        >
          {loading ? (
            <>
              <div className="spinner-border spinner-border-sm" role="status"></div>
              Sending
            </>
          ) : (
            <>
              <i className="bi bi-send"></i>
              Send
            </>
          )}
        </button>
      </div>

      {/* Model Management Info */}
      <div style={{ 
        marginTop: 16, 
        padding: 12,
        background: isDark ? '#1e293b' : '#f8fafc',
        borderRadius: 8,
        border: `1px solid ${borderColor}`,
        fontSize: '0.75rem',
        color: isDark ? '#cbd5e1' : '#6b7280'
      }}>
        <div style={{ fontWeight: 500, marginBottom: 4 }}>
          <i className="bi bi-info-circle me-1"></i>
          Model Management
        </div>
        <div style={{ display: 'flex', gap: 16, flexWrap: 'wrap' }}>
          <code style={{ 
            background: isDark ? '#0f172a' : '#ffffff', 
            padding: '2px 6px', 
            borderRadius: 4,
            fontSize: '0.7rem'
          }}>
            ollama pull llama3.2:3b
          </code>
          <code style={{ 
            background: isDark ? '#0f172a' : '#ffffff', 
            padding: '2px 6px', 
            borderRadius: 4,
            fontSize: '0.7rem'
          }}>
            ollama rm model-name
          </code>
          <code style={{ 
            background: isDark ? '#0f172a' : '#ffffff', 
            padding: '2px 6px', 
            borderRadius: 4,
            fontSize: '0.7rem'
          }}>
            ollama list
          </code>
          <code style={{ 
            background: isDark ? '#0f172a' : '#ffffff', 
            padding: '2px 6px', 
            borderRadius: 4,
            fontSize: '0.7rem'
          }}>
            this only work on localhost not as hosted 
          </code>
        </div>
      </div>
    </div>
  )
}
